#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: liga a agenda do ETL em produção (.github/workflows/etl.yml, D250).
# Grava só no GitHub (secrets e variável); nada vai para .env, para o ETL local nunca apontar para produção.
# Uso: etl/deploy/github-actions-setup.sh   (rode do Mac, com `gh auth login` feito)
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6
ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
PY="$ROOT/etl/.venv/bin/python"
export GH_REPO="${GH_REPO:-AlexandreCamerini/replica}"
ENV_FILE="/nonexistent/.env"   # sem valor sugerido de .env e sem gravar nele (write_env não é usado)

# db_probe: confere a URL no próprio banco, lida de ETL_DATABASE_URL (env, nunca argv). Imprime uma linha por fato.
db_probe() {
  ETL_DATABASE_URL="$1" "$PY" - <<'PYEOF'
import os, psycopg
url = os.environ["ETL_DATABASE_URL"]
with psycopg.connect(url, connect_timeout=15, autocommit=True) as c:
    reg = lambda t: c.execute("select to_regclass(%s) is not null", (t,)).fetchone()[0]
    print("conexao ok")
    print("schema_migrations", reg("public.schema_migrations"))
    print("etl_schedule_attempts", reg("public.etl_schedule_attempts"))
    print("sources", c.execute("select count(*) from sources").fetchone()[0] if reg("public.sources") else -1)
    lock = c.execute("select pg_try_advisory_lock(hashtext('etl.setup.probe'))").fetchone()[0]
    c.execute("select pg_advisory_unlock_all()")
    print("advisory_lock", lock)
PYEOF
}

banner "Agenda do ETL no GitHub Actions"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Pré-requisitos"
command -v gh >/dev/null || { warn "falta o gh: brew install gh"; exit 1; }
gh auth status >/dev/null 2>&1 || { warn "gh sem login: rode gh auth login e repita"; exit 1; }
[[ -x "$PY" ]] || { warn "falta $ROOT/etl/.venv (cd etl && uv venv && uv pip install -e .)"; exit 1; }
gh workflow view etl.yml >/dev/null 2>&1 || { warn "workflow etl.yml não está na main de $GH_REPO; faça o merge antes"; exit 1; }
say "Repositório: $GH_REPO (privado: cada execução gasta minutos do plano do GitHub)."
say "O cron roda a cada 3 h; na maioria das vezes não há nada vencido e o job dura poucos minutos."
note "Recarga grande (TSE, SAPL) pode levar horas; o job tem teto de 350 min."
pause "Enter para seguir"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Banco de produção: ETL_DATABASE_URL"
say "A agenda precisa de uma conexão de escrita no banco de produção (Supabase)."
open_url "https://supabase.com/dashboard/projects"
step "Abra o projeto de produção → botão Connect (topo) → aba Connection String."
step "Escolha 'Session pooler' (porta 5432, IPv4). Os runners do GitHub não têm IPv6,"
step "então a 'Direct connection' (db.<ref>.supabase.co) costuma falhar lá."
step "NÃO use o 'Transaction pooler' (porta 6543): os locks da agenda não funcionam nele."
step "Copie a URI e troque [YOUR-PASSWORD] pela senha do banco."
while :; do
  ask_secret DB_URL "Cole a URI (entrada oculta):"
  if [[ ! "$DB_URL" =~ ^postgres(ql)?:// ]]; then warn "não começa com postgres:// ou postgresql://"; continue; fi
  if [[ "$DB_URL" =~ :6543(/|\?|$) || "$DB_URL" == *pgbouncer=true* ]]; then warn "é o Transaction pooler (6543/pgbouncer); use o Session pooler"; continue; fi
  if [[ "$DB_URL" =~ @(localhost|127\.0\.0\.1|\[::1\])[:/] ]]; then warn "é um banco local; o GitHub não alcança o seu Mac"; continue; fi
  if [[ "$DB_URL" == *YOUR-PASSWORD* ]]; then warn "ainda tem [YOUR-PASSWORD]; troque pela senha"; continue; fi
  say "Testando a conexão daqui..."
  if PROBE=$(db_probe "$DB_URL" 2>&1); then break; fi
  warn "não conectou:"; PROBE="${PROBE//"$DB_URL"/<url>}"; note "$(printf '%s' "$PROBE" | tail -n 2)"
  confirm "Tentar outra URI?" || exit 1
done
note "$PROBE"
grep -q "advisory_lock True" <<<"$PROBE" || { warn "advisory lock não funcionou nesta conexão; use o Session pooler"; exit 1; }
pause "Conexão ok. Enter para conferir o schema"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Schema e seed em produção"
if grep -q "etl_schedule_attempts True" <<<"$PROBE"; then
  say "Migrações já aplicadas (etl_schedule_attempts existe)."
else
  warn "As migrações do repositório não estão todas aplicadas neste banco."
  say "db/migrate.sh aplica só as que faltam, uma transação por arquivo, e para se uma já aplicada mudou."
  if confirm "Aplicar as migrações de db/migrations/ no banco de PRODUÇÃO agora?"; then
    DATABASE_URL="$DB_URL" "$ROOT/db/migrate.sh"
  else
    warn "sem migrações a agenda vai falhar em produção; parei aqui"; exit 1
  fi
fi
SRC=$(db_probe "$DB_URL" | awk '/^sources /{print $2}')
if [[ "${SRC:-0}" -le 0 ]]; then
  warn "A tabela sources está vazia: os jobs exigem o seed (catálogo de fontes)."
  if confirm "Rodar civico-etl seed no banco de PRODUÇÃO agora?"; then
    (cd "$ROOT/etl" && ETL_DATABASE_URL="$DB_URL" "$PY" -m civico_etl.cli seed)
  else
    warn "sem seed os jobs param com \"source não existe\"; parei aqui"; exit 1
  fi
fi
say "Banco pronto ($(db_probe "$DB_URL" | awk '/^sources /{print $2}') fontes no catálogo)."
if confirm "Gravar esta URI como secret ETL_DATABASE_URL em $GH_REPO?"; then
  set_secret ETL_DATABASE_URL "$DB_URL"
else
  warn "secret não gravado; parei aqui"; exit 1
fi
unset DB_URL
pause "Enter para seguir"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Alerta (opcional): ETL_ALERT_WEBHOOK"
say "Quando algo falha, a agenda posta {\"text\": ...} nesse webhook (Slack, Discord com /slack no fim, Teams)."
say "Sem webhook, o alerta fica só como run vermelho no GitHub e no artifact last-run."
if confirm "Configurar um webhook de alerta?"; then
  step "Slack: api.slack.com/apps → seu app → Incoming Webhooks → Add New Webhook → copie a URL."
  step "Discord: canal → Editar → Integrações → Webhooks → Copiar URL, e acrescente /slack no fim."
  while :; do
    ask_secret HOOK "Cole a URL do webhook (entrada oculta):"
    [[ "$HOOK" =~ ^https:// ]] && break
    warn "precisa começar com https://"
  done
  if confirm "Mandar uma mensagem de teste para esse webhook?"; then
    if HOOK_URL="$HOOK" "$PY" -c 'import os,json,urllib.request as u; u.urlopen(u.Request(os.environ["HOOK_URL"], data=json.dumps({"text":"civico-etl: teste do alerta da agenda (D250)"}).encode(), headers={"Content-Type":"application/json"}), timeout=15).read()'; then
      say "Enviado; confira no canal."
    else
      warn "o webhook recusou o teste"; confirm "Gravar mesmo assim?" || { unset HOOK; HOOK=""; }
    fi
  fi
  [[ -n "${HOOK:-}" ]] && set_secret ETL_ALERT_WEBHOOK "$HOOK"
  unset HOOK
else
  note "sem webhook; dá para rodar este assistente de novo depois"
fi
pause "Enter para seguir"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Ligar o cron: ETL_SCHEDULE_ENABLED"
say "Com a variável em true, o workflow etl roda a cada 3 h (minuto 17) e por disparo manual."
note "Para desligar depois: gh variable set ETL_SCHEDULE_ENABLED --body false --repo $GH_REPO"
if confirm "Ligar a agenda em produção agora?"; then
  set_var ETL_SCHEDULE_ENABLED true
else
  warn "agenda não ligada; os secrets ficaram gravados"; finish; exit 0
fi
pause "Enter para seguir"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Execução de teste"
say "Teste leve: só a tarefa agenda.congresso (pauta do plenário, segundos), forçada."
say "Ele prova o secret, a conexão do runner, o lock, o check e o alerta, sem esperar as cargas grandes."
note "A primeira execução do cron num banco vazio vai carregar tudo que nunca foi carregado e pode levar horas."
note "Num banco ainda vazio o teste pode sair vermelho (exit 2) só porque o check acusa fontes nunca carregadas."
if confirm "Disparar o teste agora?"; then
  gh workflow run etl.yml -f only=agenda.congresso
  sleep 5
  RUN=$(gh run list --workflow etl.yml --event workflow_dispatch --limit 1 --json databaseId -q '.[0].databaseId')
  say "Execução $RUN: $(gh run view "$RUN" --json url -q .url)"
  if confirm "Acompanhar aqui até terminar?"; then
    gh run watch "$RUN" --exit-status && say "Passou." || warn "Terminou com falha ou alerta (exit 2). Veja o log e o artifact last-run: gh run view $RUN --log-failed"
  fi
fi

finish
